import{_ as e}from"./index-fydT0KSn.js";import{e as t,c as s,x as i,b as o,g as l,j as a,h as n,i as c}from"./vendor-BgG20VBE.js";import"./gsap-BkncV2S3.js";const r={class:"min-h-screen pt-32 pb-20 px-6 max-w-4xl mx-auto text-white"},d={class:"mt-12 text-center space-x-6"},u=e({},[["render",function(e,u){const m=c("router-link");return t(),s("div",r,[u[2]||(u[2]=i('<h1 class="text-4xl font-bold mb-8">Accessibility Statement</h1><div class="space-y-8 text-neutral-300 leading-relaxed"><div class="p-4 bg-purple-500/10 border border-purple-500/30 rounded-xl"><p class="text-purple-400 font-medium">We are committed to making this website accessible to everyone, regardless of ability or technology.</p></div><section><h2 class="text-2xl font-bold text-white mb-4">1. Our Commitment</h2><p>Jake Fieldhouse Consulting Ltd strives to ensure that our website is accessible to the widest possible audience. We aim to conform to level AA of the Web Content Accessibility Guidelines (WCAG) 2.2, which defines how to make web content more accessible to people with disabilities.</p></section><section><h2 class="text-2xl font-bold text-white mb-4">2. Accessibility Features</h2><p>This website includes the following accessibility features:</p><ul class="list-disc list-inside space-y-2 mt-4"><li><strong class="text-white">Semantic HTML:</strong> Proper heading structure and landmark regions for screen readers</li><li><strong class="text-white">Keyboard Navigation:</strong> All interactive elements are accessible via keyboard</li><li><strong class="text-white">Colour Contrast:</strong> Text meets WCAG 2.2 AA contrast requirements</li><li><strong class="text-white">Responsive Design:</strong> Content adapts to different screen sizes and zoom levels</li><li><strong class="text-white">Focus Indicators:</strong> Visible focus states for keyboard users</li><li><strong class="text-white">Reduced Motion:</strong> Respects user preferences for reduced motion</li><li><strong class="text-white">Alt Text:</strong> Descriptive alternative text for images</li></ul></section><section><h2 class="text-2xl font-bold text-white mb-4">3. Known Limitations</h2><p>While we strive for full accessibility, some limitations may exist:</p><ul class="list-disc list-inside space-y-2 mt-4"><li>Third-party embedded content (e.g., Cal.com booking widget) may have varying accessibility levels</li><li>Some older PDF documents may not be fully accessible</li><li>Complex animations may not convey the same information to all users</li></ul><p class="mt-4">We are actively working to address these limitations and improve accessibility across all content.</p></section><section><h2 class="text-2xl font-bold text-white mb-4">4. Assistive Technologies</h2><p>This website is designed to be compatible with:</p><ul class="list-disc list-inside space-y-2 mt-4"><li>Screen readers (NVDA, JAWS, VoiceOver, TalkBack)</li><li>Screen magnification software</li><li>Speech recognition software</li><li>Keyboard-only navigation</li></ul></section><section><h2 class="text-2xl font-bold text-white mb-4">5. Alternative Formats</h2><p>If you require information in an alternative format, please contact us. We will do our best to provide content in a format that meets your needs, such as:</p><ul class="list-disc list-inside space-y-2 mt-4"><li>Large print</li><li>Plain text documents</li><li>Audio descriptions</li></ul></section><section><h2 class="text-2xl font-bold text-white mb-4">6. Feedback &amp; Contact</h2><p>We welcome your feedback on the accessibility of this website. If you encounter any accessibility barriers or have suggestions for improvement, please contact us:</p><div class="mt-4 p-4 bg-neutral-800 rounded-xl"><p class="font-medium text-white">Jake Fieldhouse Consulting Ltd</p><p>Email: <a href="mailto:jake@jakefieldhouse.co.uk" class="text-blue-400 hover:underline">jake@jakefieldhouse.co.uk</a></p><p class="text-sm text-neutral-500 mt-2">Subject line: &quot;Accessibility Feedback&quot;</p></div><p class="mt-4">We aim to respond to accessibility feedback within 5 business days.</p></section><section><h2 class="text-2xl font-bold text-white mb-4">7. Enforcement</h2><p>If you are not satisfied with our response to your accessibility concern, you may contact the Equality Advisory Support Service (EASS) at <a href="https://www.equalityadvisoryservice.com/" target="_blank" rel="noopener" class="text-blue-400 hover:underline">equalityadvisoryservice.com</a>.</p></section><p class="text-neutral-500 text-sm pt-8">Last updated: February 2026</p></div>',2)),o("div",d,[l(m,{to:"/policies",class:"text-neutral-500 hover:text-white transition-colors"},{default:a(()=>[...u[0]||(u[0]=[n("← All Policies",-1)])]),_:1}),l(m,{to:"/",class:"text-neutral-500 hover:text-white transition-colors"},{default:a(()=>[...u[1]||(u[1]=[n("Back to Home",-1)])]),_:1})])])}]]);export{u as default};
